 "Контраст и резкость, %", "min": 0, "max": 100, "step": 1, "default": 50}]}, {"kind": "concat_bronze", "name": "Concat Bronze", "fields": [{"key": "tone", "label": "Тонирование, %", "min": 0, "max": 100, "step": 1, "default": 80}, {"key": "contrast", "label": "Контраст, %", "min": 0, "max": 100, "step": 1, "default": 30}]}, {"kind": "concat_cool_blue", "name": "Concat Cool Blue", "fields": [{"key": "chill", "label": "Тонирование, %", "min": 0, "max": 100, "step": 1, "default": 60}, {"key": "contrast", "label": "Контраст, %", "min": 0, "max": 100, "step": 1, "default": 30}]}, {"kind": "concat_ivory", "name": "Concat Ivory", "fields": [{"key": "matte", "label": "Матовость, %", "min": 0, "max": 100, "step": 1, "default": 60}, {"key": "warmth", "label": "Теплота, %", "min": 0, "max": 100, "step": 1, "default": 50}]}, {"kind": "concat_milk", "name": "Concat Milk", "fields": [{"key": "matte", "label": "Матовость, %", "min": 0, "max": 100, "step": 1, "default": 60}, {"key": "cool", "label": "Холод, %", "min": 0, "max": 100, "step": 1, "default": 40}]}, {"kind": "concat_matcha", "name": "Concat Matcha", "fields": [{"key": "amount", "label": "Сила, %", "min": 0, "max": 100, "step": 1, "default": 60}]}, {"kind": "concat_sage", "name": "Concat Sage", "fields": [{"key": "amount", "label": "Сила, %", "min": 0, "max": 100, "step": 1, "default": 60}]}, {"kind": "concat_clean", "name": "Concat Clean", "fields": [{"key": "amount", "label": "Сила, %", "min": 0, "max": 100, "step": 1, "default": 50}]}, {"kind":"concat_vhs","name":"Concat VHS","fields":[{"key":"bleed","label":"Растекание цвета, %","min":0,"max":100,"step":1,"default":60},{"key":"lines","label":"Полосы, %","min":0,"max":100,"step":1,"default":50}]}, {"kind":"concat_falling_dust","name":"Concat Falling Dust","fields":[{"key":"dust","label":"Пыль, %","min":0,"max":100,"step":1,"default":60},{"key":"leak","label":"Засветка, %","min":0,"max":100,"step":1,"default":50}]}, {"kind":"concat_film","name":"Concat Film","fields":[{"key":"grain","label":"Зерно, %","min":0,"max":100,"step":1,"default":40},{"key":"warmth","label":"Теплота, %","min":0,"max":100,"step":1,"default":50}]}, {"kind":"concat_digicam","name":"Concat Digicam","fields":[{"key":"flash","label":"Вспышка, %","min":0,"max":100,"step":1,"default":60},{"key":"noise","label":"Шум, %","min":0,"max":100,"step":1,"default":40}]}, {"kind":"concat_mono","name":"Concat Mono","fields":[{"key":"colour","label":"Цветной фильтр, %","min":-100,"max":100,"step":1,"default":40},{"key":"contrast","label":"Контраст, %","min":0,"max":100,"step":1,"default":40},{"key":"grain","label":"Зерно, %","min":0,"max":100,"step":1,"default":0}]}, {"kind":"concat_midnight","name":"Concat Midnight","fields":[{"key":"depth","label":"Глубина, %","min":0,"max":100,"step":1,"default":60},{"key":"grain","label":"Зерно, %","min":0,"max":100,"step":1,"default":25}]}, {"kind":"concat_marquee","name":"Concat Marquee","fields":[{"key":"lights","label":"Огни, %","min":0,"max":100,"step":1,"default":60},{"key":"depth","label":"Глубина, %","min":0,"max":100,"step":1,"default":40}]}, {"kind":"concat_retro_cartoon","name":"Concat Retro Cartoon","fields":[{"key":"levels","label":"Уровни","min":2,"max":8,"step":1,"default":5},{"key":"ink","label":"Контуры, %","min":0,"max":100,"step":1,"default":60}]}, {"kind": "concat_super8", "name": "Concat Super 8", "fields": []}, {"kind": "concat_bleach_bypass", "name": "Concat Bleach Bypass", "fields": []}, {"kind": "concat_contrast_pop", "name": "Concat Contrast Pop", "fields": [{"key": "contrast", "label": "Контраст", "min": 1, "max": 2, "step": 0.05, "default": 1.25}]}, {"kind": "concat_sharpen", "name": "Concat Sharpen", "fields": [{"key": "amount", "label": "Резкость", "min": 0.2, "max": 3, "step": 0.05, "default": 1}]}, {"kind": "concat_vignette", "name": "Concat Vignette", "fields": [{"key": "strength", "label": "Виньетка, %", "min": 10, "max": 100, "step": 1, "default": 50}]}]as const
 type Kind=typeof controls[number]['kind'];type Effect=Extract<WireVideoEffect,{kind:Kind}>
 function matches(effect:WireVideoEffect,kind:Kind):effect is Effect{return effect.kind===kind}
 // Every admitted kind has optional numeric fields or an empty parameter object.
 function defaults(kind:Kind):Effect{return{kind,parameters:{}}as Effect}
 type Field=typeof controls[number]['fields'][number]
 function value(effect:Effect,field:Field){const parameters:Readonly<Record<string,number|undefined>>=effect.parameters;return parameters[field.key]??field.default}
 function changed(effect:Effect,field:Field,value:number):Effect{const control=controls.find(c=>c.kind===effect.kind);if(!control?.fields.some(f=>f.key===field.key))throw new Error('Параметр эффекта не найден');return{...effect,parameters:{...effect.parameters,[field.key]:value}}as Effect}
 let compositionId=$derived(nestedComposition.activeCompositionId??nestedComposition.document?.root??'')
 let tracks=$derived(concatEffectInspectorTracks(nestedComposition.document,compositionId))
 function edit(track:string,clip:string,update:(effects:readonly WireVideoEffect[])=>readonly WireVideoEffect[]){const base=nestedComposition.document,session=token,composition=compositionId;return editNestedVideoEffects(composition,track,clip,update,()=>{if(base!==nestedComposition.document||session!==token||composition!==compositionId)throw new Error('Контекст эффекта изменился')})}
 function target(track:string,clip:string,index:number,kind:Kind,update:((effect:Effect)=>Effect)|null){return edit(track,clip,effects=>{const effect=effects[index];if(!effect||!matches(effect,kind))throw new Error('Эффект не найден');return update?effects.map((current,i)=>i===index?update(effect):current):effects.filter((_,i)=>i!==index)})}
</script>
{#each controls as control (control.kind)}
 <section aria-label={control.name}>
  {#each tracks as track (track.id)}
   {#if track.kind==='video'||track.kind==='image'||track.kind==='text'||track.kind==='graphic'}
    {#each track.clips as clip (clip.id)}
     <div class="row"><span>{track.name} · {clip.id}</span><button class="btn ghost sm" disabled={disabled||nestedHistory.busy||track.locked||Boolean(agentSession.lock)} onclick={()=>void edit(track.id,clip.id,effects=>[...effects,defaults(control.kind)])}>Добавить {control.name}</button></div>
     {#each (clip.effects??[]) as effect,index (index)}
      {#if matches(effect,control.kind)}
       <fieldset disabled={disabled||nestedHistory.busy||track.locked||Boolean(agentSession.lock)}>
        <legend>{control.name} {index+1}</legend>
        {#each control.fields as field (field.key)}<label>{field.label}<input type="number" min={field.min} max={field.max} step={field.step} value={value(effect,field)} aria-label={`${clip.id} ${control.name} ${field.key}`} onchange={event=>{const next=Number(event.currentTarget.value);void target(track.id,clip.id,index,control.kind,current=>changed(current,field,next))}}/></label>{/each}
        <div class="row"><button class="btn ghost sm" onclick={()=>void target(track.id,clip.id,index,control.kind,()=>defaults(control.kind))}>Сбросить {control.name}</button><button class="btn ghost sm" onclick={()=>void target(track.id,clip.id,index,control.kind,null)}>Удалить {control.name}</button></div>
       </fieldset>
      {/if}
     {/each}
    {/each}
   {/if}
  {/each}
 </section>
{/each}
